#!/bin/bash
set -euo pipefail

HERDR="$HOME/herdr"
TASK="$HERDR/herdr-task.py"
PROJECTS="$HERDR/herdr_projects.py"
TOPO="$HERDR/herdr_topology.py"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$HERDR/topology-selfheal-backup-$STAMP"

mkdir -p "$BACKUP"
cp "$TASK" "$BACKUP/herdr-task.py"
cp "$PROJECTS" "$BACKUP/herdr_projects.py"
[ -f "$TOPO" ] && cp "$TOPO" "$BACKUP/herdr_topology.py" || true

echo '' | base64 --decode > "$TOPO"
chmod +x "$TOPO"

echo '' | base64 --decode | python3

python3 -m py_compile "$TOPO" "$TASK" "$PROJECTS"

echo
echo "=== STATIC VERIFY ==="
grep -nE 'ensure_stage_topology|Live topology is the source of truth' "$TASK" | head -20
grep -nE 'Stage tabs/anchors are repairable topology' "$PROJECTS" | head -10

cd "$HERDR"
git add herdr_topology.py herdr-task.py herdr_projects.py
git commit -m "feat: self-heal stage tabs and anchors before task launch" || true

echo
echo "HERDR_TOPOLOGY_SELFHEAL_INSTALL: PASS"
echo "Backup: $BACKUP"
echo
echo "Rules now:"
echo "  stage key/label = identity"
echo "  tab_id/anchor_pane_id = runtime cache only"
echo "  missing tab = recreate"
echo "  missing anchor = recreate"
echo "  historical task panes are never repurposed as anchors"
